import type { ErasureRequest, ErasureStatus } from '../../../packages/contracts/src/domain.js';

interface ErasureRow {
  id: string;
  merchant_id: string;
  customer_id: string;
  status: ErasureStatus;
  attempts: number;
  last_error: string | null;
  created_at: Date;
  updated_at: Date;
  completed_at: Date | null;
}

function toErasureRequest(row: ErasureRow): ErasureRequest {
  return {
    id: row.id,
    merchantId: row.merchant_id,
    customerId: row.customer_id,
    status: row.status,
    attempts: row.attempts,
    lastError: row.last_error,
    createdAt: row.created_at.toISOString(),
    updatedAt: row.updated_at.toISOString(),
    completedAt: row.completed_at ? row.completed_at.toISOString() : null,
  };
}

export class ErasureRepository {
  async findByCustomer(client: pg.PoolClient, merchantId: string, customerId: string): Promise<ErasureRequest | undefined> {
    const result = await client.query<ErasureRow>(
      `SELECT id,merchant_id,customer_id,status,attempts,last_error,created_at,updated_at,completed_at
       FROM privacy.erasure_requests WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return result.rows[0] ? toErasureRequest(result.rows[0]) : undefined;
  }

  async findById(client: pg.PoolClient, merchantId: string, requestId: string): Promise<ErasureRequest | undefined> {
    const result = await client.query<ErasureRow>(
      `SELECT id,merchant_id,customer_id,status,attempts,last_error,created_at,updated_at,completed_at
       FROM privacy.erasure_requests WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId],
    );
    return result.rows[0] ? toErasureRequest(result.rows[0]) : undefined;
  }

  async create(client: pg.PoolClient, input: { merchantId: string; customerId: string; apiKeyId: string }): Promise<ErasureRequest> {
    const result = await client.query<ErasureRow>(
      `INSERT INTO privacy.erasure_requests(merchant_id,customer_id,requested_by_key)
       VALUES($1,$2,$3)
       ON CONFLICT(merchant_id,customer_id) DO UPDATE SET updated_at=privacy.erasure_requests.updated_at
       RETURNING id,merchant_id,customer_id,status,attempts,last_error,created_at,updated_at,completed_at`,
      [input.merchantId, input.customerId, input.apiKeyId],
    );
    const row = result.rows[0]!;
    return toErasureRequest(row);
  }
}"}

