          );
        } catch (error) {
          const existing = await this.repository.findByCustomer(client, merchantId, customerId);
          if (!existing) throw error;
          request = existing;
        }
      }

      const body: ErasureRequest = request;
      await completeIdempotency(client, merchantId, idempotencyScope, idempotencyKey, 202, body);
      return { status: 202, body };
    });
  }

  async find(merchantId: string, requestId: string): Promise<ErasureRequest | undefined> {
    return new ErasureRepository().findById((await import('../../../packages/database/src/pool.js')).pool, merchantId, requestId);
  }
}

