function redactedSnapshot(previous: Record<string, unknown> | null): Record<string, unknown> {
  if (!previous) return { redacted: true };
  const keys = Object.keys(previous).filter((key) => key !== 'currency' && key !== 'amount' && key !== 'tax' && key !== 'lines');
