     WHERE merchant_id=$1 AND customer_id=$2 AND destination IS NOT NULL`,
    [merchantId, customerId],
  );
  await client.query(
    `UPDATE operations.notifications SET destination=NULL
     WHERE merchant_id=$1 AND customer_id=$2 AND destination IS NOT NULL`,
    [merchantId, customerId],
  );
  await client.query(
    `UPDATE operations.email_deliveries SET destination=NULL,subject=NULL,text_body=NULL,html_body=NULL,template='erased'
     WHERE merchant_id=$1 AND customer_id=$2 AND status IN ('pending','processing','retry','failed')
       AND (destination IS NOT NULL OR subject IS NOT NULL)`,
    [merchantId, customerId],
  );
  await client.query(
    `UPDATE operations.outbox_events
     SET payload=jsonb_set(payload,'{customerEmail}','null'::jsonb,true)
     WHERE merchant_id=$1 AND aggregate_id=$2::text AND payload ? 'customerEmail'`,
    [merchantId, customerId],
  );
  await client.query(
    `UPDATE operations.outbox_events
     SET payload=jsonb_set(payload,'{customerSnapshot}','{"redacted":true}'::jsonb,true)
     WHERE merchant_id=$1 AND payload->>'customerId'=$2 AND jsonb_typeof(payload->'customerSnapshot')='object'
       AND NOT (payload->'customerSnapshot' ? 'redacted')`,
    [merchantId, customerId],
  );
  await client.query(
    `UPDATE operations.inbox_events
     SET payload=jsonb_set(payload,'{customerEmail}','null'::jsonb,true)
     WHERE payload->>'merchantId'=$1 AND payload->>'customerId'=$2 AND payload ? 'customerEmail'`,
    [merchantId, customerId],
  );
}

async function scrubDocumentManifests(client: pg.PoolClient, merchantId: string, customerId: string): Promise<ManifestRow[]> {
  const result = await client.query<ManifestRow>(
    `UPDATE operations.document_manifests
     SET metadata=jsonb_set(metadata,'{customerId}','"redacted"'::jsonb,true)
     WHERE merchant_id=$1 AND metadata->>'customerId'=$2
       AND NOT (metadata->>'customerId'='redacted')
     RETURNING object_key,document_type,metadata`,
    [merchantId, customerId],
  );
  return result.rows;
}

async function scrubProviderSandbox(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
  await client.query(
    `UPDATE provider_sandbox.customers SET email=$3,name=$4,external_reference=$5
     WHERE merchant_id=$1 AND payflow_customer_id=$2`,
    [merchantId, customerId, REDACTED_EMAIL, REDACTED_NAME, `erased_${customerId.replaceAll('-', '')}`],
  );
  await client.query(
    `UPDATE provider_sandbox.payment_intents SET provider_customer_id=NULL
     WHERE merchant_id=$1 AND provider_customer_id IN (
       SELECT provider_customer_id FROM customers.provider_customer_mappings
       WHERE merchant_id=$1 AND customer_id=$2
     )`,
    [merchantId, customerId],
  );
}

async function deleteCapturedEmails(mailpit: string, email: string): Promise<void> {
  if (!email || email === REDACTED_EMAIL) return;
  try {
    await fetch(`${mailpit.replace(/\/$/, '')}/api/v1/messages`, {
      method: 'DELETE',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ query: `to:"${email}"` }),
    });
  } catch {
    // best effort; mailpit may be unreachable in some envs
  }
}

async function redactDocument(objectKey: string, manifest: ManifestRow): Promise<void> {
  try {
    const stream = await objectStore.getObject(DOCUMENT_BUCKET, objectKey);
    const chunks: Buffer[] = [];
    for await (const chunk of stream) chunks.push(chunk as Buffer);
    const original = Buffer.concat(chunks).toString('utf8');
    let parsed: unknown;
    try { parsed = JSON.parse(original); } catch { parsed = null; }
    let replacement: string;
    if (parsed && typeof parsed === 'object') {
      const redacted = { ...(parsed as Record<string, unknown>) };
      for (const key of ['customer', 'customerId', 'customerEmail', 'customerName', 'email', 'name']) {
        if (key in redacted) redacted[key] = REDACTED_STRING;
      }
      replacement = JSON.stringify({ ...redacted, redacted: true });
    } else if (manifest.document_type === 'customer_import') {
      replacement = JSON.stringify({ redacted: true, reason: 'erasure_requested' });
    } else {
      replacement = `[redacted per data deletion request]`;
    }
    await objectStore.putObject(DOCUMENT_BUCKET, objectKey, Buffer.from(replacement, 'utf8'), {
      'Content-Type': 'application/json',
      'X-Redacted-Reason': 'erasure_requested',
    });
  } catch {
    // best effort; missing documents are treated as already-redacted
  }
}

async function clearSearchIndex(opensearch: OpenSearch, merchantId: string, customerId: string): Promise<void> {
  try {
    await opensearch.delete({ index: CUSTOMER_INDEX, id: `${merchantId}:${customerId}`, refresh: true });
  } catch (error: unknown) {
    if (error && typeof error === 'object' && 'meta' in error) return;
    throw error;
  }
}

async function clearRedisCache(redis: Redis, merchantId: string, customerId: string): Promise<void> {
  await redis.del(`merchant:${merchantId}:customer:${customerId}`);
  await redis.del(`merchant:${merchantId}:customer:${customerId}:activity`);
}

export async function markProcessing(requestId: string): Promise<void> {
  await pool.query(
    `UPDATE privacy.erasure_requests SET status='processing',attempts=attempts+1,updated_at=now(),last_error=NULL
     WHERE id=$1`,
    [requestId],
  );
}

export async function markCompleted(requestId: string): Promise<void> {
  await pool.query(
    `UPDATE privacy.erasure_requests SET status='completed',completed_at=now(),updated_at=now(),last_error=NULL
     WHERE id=$1`,
    [requestId],
  );
}

export async function markFailed(requestId: string, error: unknown): Promise<void> {
  const message = error instanceof Error ? error.message.slice(0, 300) : String(error).slice(0, 300);
  await pool.query(
    `UPDATE privacy.erasure_requests SET status='failed',updated_at=now(),last_error=$2
     WHERE id=$1`,
    [requestId, message],
  );
}

export async function runCleanup(payload: ErasureJobPayload): Promise<void> {
  const settings = config();
  const redis = new Redis(settings.REDIS_URL);
  const opensearch = new OpenSearch({ node: settings.OPENSEARCH_NODE });
  try {
    const identity = await transaction(async (client) => readCustomerIdentity(client, payload.merchantIdHint ?? '', payload.customerId));
    // We don't actually need merchantIdHint; look up by request id
    const request = await pool.query<{ merchant_id: string; customer_id: string; email: string; status: string }>(
      `SELECT er.merchant_id,er.customer_id,c.email,er.status
       FROM privacy.erasure_requests er
       LEFT JOIN customers.customers c ON c.merchant_id=er.merchant_id AND c.id=er.customer_id
       WHERE er.id=$1`, [payload.requestId],
    );
    const row = request.rows[0];
    if (!row) throw new Error(`erasure_request ${payload.requestId} not found`);
    const merchantId = row.merchant_id;
    const customerId = row.customer_id;
    const originalEmail = row.email ?? '';

    const manifests = await transaction(async (client) => {
      await scrubCustomerRow(client, merchantId, customerId);
      await removeCustomerChildren(client, merchantId, customerId);
      await scrubPaymentMethods(client, merchantId, customerId);
      await scrubSupportTickets(client, merchantId, customerId);
      await scrubPaymentSnapshots(client, merchantId, customerId);
      await scrubOperations(client, merchantId, customerId);
      await scrubProviderSandbox(client, merchantId, customerId);
      return scrubDocumentManifests(client, merchantId, customerId);
    });

    await clearSearchIndex(opensearch, merchantId, customerId);
    await clearRedisCache(redis, merchantId, customerId);
    for (const manifest of manifests) await redactDocument(manifest.object_key, manifest);
    await deleteCapturedEmails(settings.MAILPIT_API_URL, originalEmail);
    // silence unused warnings while keeping contract clear
    void identity;
  } finally {
    redis.disconnect();
    await opensearch.close();
  }
}"}

