{"security_risk":"LOW","summary":"Create privacy-worker main","command":"create","path":"/workspace/source/apps/privacy-worker/src/main.ts","file_text":"import { randomUUID } from 'node:crypto';
import { v4 as uuid } from 'uuid';
import { EVENT_TYPES } from '../../../packages/contracts/src/events.js';
import { transaction } from '../../../packages/database/src/pool.js';
import { addOutboxEvent } from '../../../packages/messaging/src/outbox.js';
import { logger } from '../../../packages/observability/src/logger.js';
import { startOutboxPublisher } from '../../../packages/messaging/src/publisher.js';
import {
  claimJob, completeJob, failJob, recoverExpiredJobLeases, type ClaimedJob,
} from '../../../packages/operations/src/job-lifecycle.js';
import { markCompleted, markFailed, markProcessing, runCleanup, type ErasureJobPayload } from './cleanup.js';

process.env.SERVICE_NAME = 'privacy-worker';
const workerId = `privacy-worker-${randomUUID()}`;
const controller = new AbortController();

async function complete(job: ClaimedJob<ErasureJobPayload>): Promise<void> {
  await transaction(async (client) => {
    await markProcessing(job.payload.requestId);
    try {
      await runCleanup(job.payload);
    } catch (error) {
      await client.query(
        `UPDATE privacy.erasure_requests SET status='failed',updated_at=now(),last_error=$2 WHERE id=$1`,
        [job.payload.requestId, error instanceof Error ? error.message.slice(0, 300) : String(error).slice(0, 300)],
      );
      throw error;
    }
    await markCompleted(job.payload.requestId);
    await addOutboxEvent(client, {
      eventType: EVENT_TYPES.ERASURE_COMPLETED,
      aggregateType: 'erasure_request',
      aggregateId: job.payload.requestId,
      merchantId: job.merchant_id,
      correlationId: uuid(),
      payload: { requestId: job.payload.requestId, customerId: job.payload.customerId, status: 'completed' },
    });
    await completeJob(client, job);
  });
}

async function run(signal: AbortSignal): Promise<void> {
  let lastLeaseRecovery = 0;
  while (!signal.aborted) {
    if (Date.now() - lastLeaseRecovery > 30_000) {
      await recoverExpiredJobLeases('privacy');
      lastLeaseRecovery = Date.now();
    }
    const job = await claimJob<ErasureJobPayload>('privacy', workerId);
    if (!job) { await new Promise((resolve) => setTimeout(resolve, 250)); continue; }
    try { await complete(job); }
    catch (error) {
      logger.error({ error, jobId: job.id }, 'erasure job failed');
      try {
        await transaction(async (client) => {
          await failJob(client, job, error);
          await markFailed(job.payload.requestId, error);
          if (job.attempts >= job.max_attempts) {
            await addOutboxEvent(client, {
              eventType: EVENT_TYPES.ERASURE_FAILED,
              aggregateType: 'erasure_request',
              aggregateId: job.payload.requestId,
              merchantId: job.merchant_id,
              correlationId: uuid(),
              payload: { requestId: job.payload.requestId, customerId: job.payload.customerId, status: 'failed' },
            });
          }
        });
      } catch (innerError) {
        logger.error({ innerError, jobId: job.id }, 'failed to record job failure');
      }
    }
  }
}

void startOutboxPublisher(controller.signal);
void run(controller.signal);
logger.info({ workerId }, 'privacy worker started');
for (const signal of ['SIGTERM', 'SIGINT'] as const) process.on(signal, () => controller.abort());"}

